def main() -> None:
    dados = json.loads(ARQ.read_text(encoding="utf-8"))
    por_id = {f["id"]: f for f in dados}
    for codigo, extras in VARIACOES_EXTRAS.items():
        variacoes = por_id[codigo]["variacoes"]
        variacoes += [v for v in extras if v not in variacoes]
    novas = 0
    for codigo, categoria, risco, pergunta, variacoes, chaves, resposta in NOVAS:
        if codigo in por_id:
            continue
        dados.append({
            "id": codigo, "categoria": categoria, "pergunta": pergunta, "variacoes": variacoes,
            "palavras_chave": chaves, "resposta": resposta, "fonte": FONTE, "revisado_em": None,
            "status": "pendente_validacao" if categoria == "atendimento_comercial" else "rascunho",
            "nivel_risco": risco,
        })
        novas += 1
    # Destino fixo do repositório (knowledge/faq.json), não derivado do conteúdo lido.
    ARQ.write_text(json.dumps(dados, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")  # NOSONAR
    print(f"{novas} FAQs novas | total {len(dados)} FAQs | {sum(len(f['variacoes']) for f in dados)} variações")


if __name__ == "__main__":
    main()
